"use server";

import {
  hasErrors,
  readContactForm,
  successMessage,
  validateContact,
  type ContactErrors,
  type ContactValues,
} from "@/lib/contact";

export type ContactState = {
  values: ContactValues;
  errors: ContactErrors;
  success: string | null;
};

export async function sendMessage(
  _previous: ContactState,
  formData: FormData,
): Promise<ContactState> {
  const values = readContactForm(formData);
  const errors = validateContact(values);
  if (hasErrors(errors)) {
    return { values, errors, success: null };
  }
  // Nothing is stored: the message is simply accepted.
  return {
    values: { name: "", email: "", message: "" },
    errors: {},
    success: successMessage(values.name),
  };
}
