import { NextResponse, type NextRequest } from "next/server";
import { listBookSlugs } from "@/lib/book-files";

// A path no route matches: Next.js answers it with the 404 page and status.
const NOT_FOUND_PATH = "/books/_unknown/_not-found";

/**
 * Sends book URLs whose slug matches no book to the 404 page before rendering,
 * so they get the fully server-rendered not-found page with status 404.
 */
export async function proxy(request: NextRequest) {
  const raw = request.nextUrl.pathname.slice("/books/".length).replace(/\/$/, "");
  let slug: string;
  try {
    slug = decodeURIComponent(raw);
  } catch {
    slug = raw;
  }
  const slugs = await listBookSlugs();
  if (slugs.includes(slug)) return NextResponse.next();
  return NextResponse.rewrite(new URL(NOT_FOUND_PATH, request.url));
}

export const config = {
  matcher: "/books/:slug",
};
